export default function findBestPath(t,e,n){const o=new Map;for(const t of n.entries())o.set(t[0],t[1].copy());let s=[];const f=[],r=o.get(t),i=o.get(e);let c=!1;findCost(r,i),s.push(r);let h=r;do{if(h=findLowestCost(s),s=s.filter(t=>t.key!==h.key),f.push(h),h.key===e)c=!0;else for(let t of h.neighbours)if(t=o.get(t.key),!f.find(e=>e===t))if(s.find(e=>e===t)){const e=findCost(t.copy(h),i);e.f<t.cost.f&&(t.parent=h,t.cost=e)}else t.parent=h,findCost(t,i),s.push(t)}while(!c);return findPath(h)}function findLowestCost(t){if(t.length<=0)throw new Error("Open is empty !");let e=t[0];for(let n=1;n<t.length;n++)t[n].cost.f<e.cost.f&&(e=t[n]);return e}function findPath(t,e=[]){return t?(e.push(t.key),findPath(t.parent,e)):e.reverse()}function findCost(t,e){if(t.parent){const e=Math.sqrt((t.x-t.parent.x)**2+(t.y-t.parent.y)**2);t.cost.g=t.parent.cost.g+e}else t.cost.g=0;return t.cost.h=Math.sqrt((e.x-t.x)**2+(e.y-t.y)**2),t.cost.f=t.cost.g+t.cost.h,t.cost}